package glitch

import data.glitch_lib

password_indicators := {"password", "passwd", "secret", "token", "key", "credential", "auth"}

is_empty_value(value) {
    value.ir_type == "String"
    count(trim(value.value, " \t\n\r")) == 0
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

contains_password_indicator(name) {
    lower_name := lower(name)
    indicator := password_indicators[_]
    contains(lower_name, indicator)
}

# Extract the final component from bracket or dot notation names
extract_final_component(name) = component {
    # Handle bracket notation like default['yum']['main']['password']
    regex.match(`.*\['([^']+)'\]$`, name, groups)
    component := groups[1]
} else = component {
    # Handle dot notation or simple names
    parts := split(name, ".")
    count(parts) > 0
    component := parts[count(parts) - 1]
} else = name {
    # Fallback to original name
    true
}

is_password_field_name(name) {
    final := extract_final_component(name)
    contains_password_indicator(final)
}

# Check for authentication context patterns
has_auth_context_pattern(name) {
    lower_name := lower(name)
    # Look for patterns like subscription_manager, git credentials, etc.
    contains(lower_name, "subscription")
} else {
    lower_name := lower(name)
    contains(lower_name, "manager")
} else {
    lower_name := lower(name)
    contains(lower_name, "login")
} else {
    lower_name := lower(name)
    contains(lower_name, "account")
} else {
    lower_name := lower(name)
    contains(lower_name, "yum")
} else {
    lower_name := lower(name)
    contains(lower_name, "access")
} else {
    lower_name := lower(name)
    contains(lower_name, "api")
} else {
    lower_name := lower(name)
    regex.match(`_pass(word)?$`, lower_name)
}

# For Ansible: check if we're in a defaults file that sets optional empty values
is_likely_optional_default(path, name) {
    # Check if path indicates this is a defaults file with common patterns
    contains(lower(path), "defaults")
    contains(lower(path), "group_vars")
}

# For Ansible: check if the variable name follows optional default naming
is_optional_default_pattern(name) {
    lower_name := lower(name)
    # Double underscore often indicates internal/optional variables in Ansible
    contains(lower_name, "__")
}

check_key_value(kv) {
    is_password_field_name(kv.name)
    is_empty_value(kv.value)
    not is_exempt_optional(kv)
}

# Determine if this is likely an intentionally optional empty default
is_exempt_optional(kv) {
    # Strong signals this is an intentionally empty optional default
    is_optional_default_pattern(kv.name)
}

# For Ansible vars in defaults files, require additional context
requires_additional_context(kv, parent) {
    parent.type == "vars"
    is_likely_optional_default(parent.path, kv.name)
    not has_auth_context_pattern(kv.name)
}

