package glitch

import data.glitch_lib

password_indicators := {"password", "passwd", "secret", "token", "key", "credential", "auth", "passcode", "passphrase"}

is_empty_value(value) {
    value.ir_type == "String"
    count(trim(value.value, " \t\n\r")) == 0
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

contains_password_indicator(name) {
    lower_name := lower(name)
    indicator := password_indicators[_]
    contains(lower_name, indicator)
}

extract_final_component(name) = component {
    matches := regex.find_all_string_submatch_n(`.*\['([^']+)'\]$`, name, 1)
    count(matches) > 0
    count(matches[0]) > 1
    component := matches[0][1]
} else = component {
    parts := split(name, ".")
    count(parts) > 0
    component := parts[count(parts) - 1]
} else = name {
    true
}

is_password_field_name(name) {
    lower_name := lower(name)
    contains_password_indicator(lower_name)
} else {
    final := extract_final_component(name)
    contains_password_indicator(final)
}

has_auth_context_pattern(name) {
    lower_name := lower(name)
    auth_patterns := {"subscription", "manager", "login", "account", "yum", "access", "api", "ssh", "mysql", "postgres", "database", "db", "jenkins", "gitlab", "proxy", "client", "ssl"}
    pattern := auth_patterns[_]
    contains(lower_name, pattern)
}

is_ansible_defaults_path(path) {
    contains(lower(path), "defaults")
} else {
    contains(lower(path), "group_vars")
}

is_internal_ansible_pattern(name) {
    lower_name := lower(name)
    contains(lower_name, "__")
}

# Check if this appears to be an intentionally unset optional default
is_likely_unset_optional(kv, parent) {
    parent.type == "vars"
    is_ansible_defaults_path(parent.path)
    not has_auth_context_pattern(kv.name)
    is_internal_ansible_pattern(kv.name)
} else {
    # Chef attributes files with nil defaults for optional configs
    parent.type == "script"
    kv.value.ir_type == "Null"
    not has_auth_context_pattern(kv.name)
}

check_key_value(kv, parent) {
    is_password_field_name(kv.name)
    is_empty_value(kv.value)
    not is_likely_unset_optional(kv, parent)
}

collect_keys_values(node, kvs) {
    node.ir_type == "KeyValue"
    kvs := {node}
} else {
    node.ir_type == "Hash"
    kvs := {kv |
        [_, child] := walk(node.value)
        child.ir_type == "KeyValue"
        kv := child
    }
} else {
    node.ir_type == "Array"
    kvs := {kv |
        [_, elem] := walk(node.value)
        elem.ir_type == "Hash"
        [_, inner] := walk(elem.value)
        inner.ir_type == "KeyValue"
        kv := inner
    }
} else {
    kvs := set()
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables directly in the unit block
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    check_key_value(var, parent)

    result := {
        "type": "sec_empty_pass",
        "element": var,
        "path": parent.path,
        "description": "Empty Password in Configuration File - Password fields should not be empty or null. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    check_key_value(attr, parent)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty Password in Configuration File - Password fields should not be empty or null. (CWE-258)"
