    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    inner_kvs := collect_keys_values(attr.value, _)
    inner_kv := inner_kvs[_]

    check_key_value(inner_kv, parent)

    result := {
        "type": "sec_empty_pass",
        "element": inner_kv,
